mapper.select:
SELECT MAX(sort_order)
FROM production_schedule
WHERE schedule_date = #{date}

SELECT lot_no
FROM production_schedule
WHERE schedule_date = #{date}
  AND product_code = #{productCode}
  AND lot_no IS NOT NULL
  AND lot_no != ''

  AND id != #{exceptId}

mapper.insert:
INSERT INTO production_schedule (
    schedule_date, client_code, product_code, order_qty, note, logistics_date,
    source_order_id, is_stock_production, lot_no, sort_order, created_at
) VALUES (
    #{scheduleDate}, #{clientCode}, #{productCode}, #{orderQty}, #{note}, #{logisticsDate},
    #{sourceOrderId,jdbcType=INTEGER}, #{isStockProduction,jdbcType=INTEGER}, #{lotNo}, #{sortOrder,jdbcType=INTEGER}, #{createdAt}
)

mapper.update:
UPDATE production_schedule
SET lot_no = #{lotNo}
WHERE id = #{id}

UPDATE materials
SET stock_qty = COALESCE(stock_qty, 0) + #{qty,jdbcType=DOUBLE}
WHERE code = #{code}

mapper.select:
SELECT material_code AS "materialCode", qty_used AS "qtyUsed"
FROM production_material_usage
WHERE schedule_id = #{scheduleId}

mapper.update:
UPDATE sales_order
SET imported_production = #{value}
WHERE id = #{id}

UPDATE logistics_schedule
SET lot_id = #{lotId}
WHERE source_order_id = #{sourceOrderId}
  AND lot_id IS NULL
